// Generator for the Gigabyte Aorus laptop module device table.
// Usage: node scripts/openrgb/port-gigabyte-aorus-laptop-devices.mjs <openrgb-root> <commit>
// Reads GigabyteAorusLaptopControllerDetect.cpp and regenerates
// modules/gigabyte-aorus-laptop/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'GigabyteAorusLaptopController');
const detect = fs.readFileSync(path.join(family, 'GigabyteAorusLaptopControllerDetect.cpp'), 'utf8');

const constants = Object.fromEntries(
  [...detect.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.GIGABYTE_AORUS_LAPTOP_VID == null) {
  throw new Error('GIGABYTE_AORUS_LAPTOP_VID not found');
}
const n = (s) => constants[s.trim()] ?? Number.parseInt(s.trim(), 16);

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR_IPU\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*GIGABYTE_AORUS_LAPTOP_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*,\s*(\d+)\s*,\s*0x([0-9A-Fa-f]+)\s*,\s*0x([0-9A-Fa-f]+)\s*\)/g,
)) {
  const pid = n(m[3]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in detector row ${m[1]}`);
  // upstream: only the Keyboard handlers route a direct-mode capable controller.
  rows.push({
    name: m[1],
    handler: m[2],
    vid: constants.GIGABYTE_AORUS_LAPTOP_VID,
    pid,
    interface: Number.parseInt(m[4], 10),
    usagePage: Number.parseInt(m[5], 16),
    usage: Number.parseInt(m[6], 16),
    keyboard: m[2] === 'DetectGigabyteAorusLaptopKeyboardControllers',
  });
}
if (rows.length === 0) throw new Error('no Gigabyte Aorus laptop detectors parsed');
if (rows.length !== 4) throw new Error(`expected 4 detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'gigabyte-aorus-laptop', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-gigabyte-aorus-laptop-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)}, keyboard: ${d.keyboard} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Gigabyte Aorus laptop HID detectors`);